<?php
require_once 'config/koneksi.php';
$id=(int)($_GET['id']??0);
$stmt=$conn->prepare("SELECT p.*,k.nama_kategori,s.nama_toko,s.alamat AS alamat_toko FROM produk p JOIN kategori k ON k.id_kategori=p.id_kategori JOIN penjual s ON s.id_penjual=p.id_penjual WHERE p.id_produk=?");$stmt->bind_param('i',$id);$stmt->execute();$p=$stmt->get_result()->fetch_assoc();
if(!$p){http_response_code(404);$judul='Bunga tidak ditemukan';include 'includes/header.php';echo '<div class="shop-panel p-5 text-center"><h3>Oops, bunganya belum ada 🌷</h3><a class="btn btn-success mt-3" href="index.php">Kembali ke toko</a></div>';include 'includes/footer.php';exit;}
$judul=$p['nama_produk'];include 'includes/header.php';?>
<div class="page-title"><a href="index.php" class="text-decoration-none" style="color:#bd5d83">← Kembali ke koleksi</a></div><div class="row g-4 align-items-center mb-5"><div class="col-lg-6"><img class="product-detail-image" src="<?= e(gambar_src($p['gambar'])) ?>" alt="<?= e($p['nama_produk']) ?>"></div><div class="col-lg-6 px-lg-5"><span class="badge"><?= e($p['nama_kategori']) ?></span><h1 class="mt-3 mb-2"><?= e($p['nama_produk']) ?></h1><div class="product-price fs-3 mb-3"><?= rupiah($p['harga']) ?></div><p class="text-muted" style="line-height:1.9"><?= nl2br(e($p['deskripsi'])) ?></p><div class="shop-panel p-3 mb-4"><div>♡ Dirangkai dengan penuh perhatian</div><div class="small text-muted mt-1">Tersedia <?= (int)$p['stok'] ?> · <?= e($p['nama_toko']) ?></div></div><?php if(is_admin()): ?><div class="alert alert-info">Admin sedang dalam mode pengelolaan. Logout untuk berbelanja sebagai pembeli.</div><?php elseif($p['stok']>0): ?><form method="post" action="keranjang.php" class="d-flex flex-wrap gap-2"><?= csrf_field() ?><input type="hidden" name="aksi" value="tambah"><input type="hidden" name="id" value="<?= (int)$p['id_produk'] ?>"><input type="number" name="jumlah" class="form-control" style="max-width:100px" value="1" min="1" max="<?= (int)$p['stok'] ?>"><button class="btn btn-success flex-fill">Tambah ke keranjang ♡</button></form><?php else: ?><div class="alert alert-warning">Bunga ini sedang habis.</div><?php endif; ?></div></div>
<?php include 'includes/footer.php'; ?>